import{_ as a,o as r,c as n,a4 as t}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Homa Offering (Homahuti) Evidence Audit","description":"","frontmatter":{},"headers":[],"relativePath":"reference/38-yajna-homam-evidence-audit.md","filePath":"reference/38-yajna-homam-evidence-audit.md","lastUpdated":1787887572000}'),i={name:"reference/38-yajna-homam-evidence-audit.md"};function o(d,e,s,h,u,c){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="homa-offering-homahuti-evidence-audit" tabindex="-1">Homa Offering (Homahuti) Evidence Audit <a class="header-anchor" href="#homa-offering-homahuti-evidence-audit" aria-label="Permalink to &quot;Homa Offering (Homahuti) Evidence Audit&quot;">​</a></h1><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p>The <code>yajna</code> compatibility key now represents the narrower, source-verified <strong>Homa offering (Homahuti)</strong> election. It applies both computations in Muhurta Chintamani, Nakshatra-prakarana 35-36 as hard gates. The former Purna, Jaya, weekday and fixed-Lagna proxies have been removed.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li><strong>MC-HINDI-IA</strong> — <em>Muhurta Chintamani</em>, Hindi edition, Nakshatra-prakarana, “Homahuti Muhurta” and “Agnivasa,” verses 35-36, printed pp. 43-44; Internet Archive full-text OCR lines 2773-2796.</li></ul><h2 id="implemented-reading" tabindex="-1">Implemented reading <a class="header-anchor" href="#implemented-reading" aria-label="Permalink to &quot;Implemented reading&quot;">​</a></h2><p>Verse 35 counts the active lunar Nakshatra inclusively from Surya&#39;s Nakshatra. The 27 Nakshatras form nine consecutive groups of three, assigned in order to Surya, Budha, Shukra, Shani, Chandra, Mangala, Guru, Rahu and Ketu. The offering is rejected for a <code>khala</code> (malefic) group; automation therefore admits the natural-benefic groups Budha, Shukra, Chandra and Guru and rejects Surya, Mangala, Shani, Rahu and Ketu.</p><p>Verse 36 numbers the Tithi from Shukla Pratipat across the full 30-Tithi lunar month, adds one, adds the weekday number counted Sunday=1 through Saturday=7, and takes modulo four. Remainders 3 and 0 place Agni on earth and admit Homa; remainder 1 places Agni in heaven and remainder 2 in the underworld, so both are rejected.</p><p>Both tests are recomputed at each slot start using the selected Panchangam engine&#39;s Sun and Moon model. Passing slots disclose the group lord and the Agnivasa remainder in <code>activity_match</code>.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><p>This verifies an election for a fire offering, not a universal election for every ceremony called Yajna. The officiating priest&#39;s Kalpa/Sampradaya rules, ritual arrangements and fire safety remain explicit manual prerequisites.</p>',11)])])}const f=a(i,[["render",o]]);export{m as __pageData,f as default};
